<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/partners.php';
$user=require_role('admin','staf_bkk');$canMou=user_can($user,'mou');
$campusDirectory=$campusDirectory??false;$ready=partner_profiles_ready();
try{[$q,$kind,$cluster,$where,$params]=partner_list_filters($_GET,$campusDirectory,$ready);}catch(InvalidArgumentException $exception){http_response_code(400);exit(e($exception->getMessage()));}
$from=' FROM mitra m'.($ready?' LEFT JOIN mitra_profiles p ON p.mitra_id=m.id':'').' WHERE '.$where;
$total=(int)panel_query('SELECT COUNT(*)'.$from,$params)->fetchColumn();$pages=max(1,(int)ceil($total/20));$page=min($pages,positive_id($_GET['page']??'1')??1);
$extra=$ready?'p.klaster,p.negara,p.alamat_lengkap,p.pic_nama,p.pic_kontak,COALESCE(p.version,0) AS profile_version':"NULL AS klaster,'' AS negara,'' AS alamat_lengkap,'' AS pic_nama,'' AS pic_kontak,0 AS profile_version";
$items=panel_query('SELECT m.*,'.$extra.$from.' ORDER BY m.nama,m.id LIMIT :limit OFFSET :offset',$params+['limit'=>20,'offset'=>($page-1)*20])->fetchAll();
$path=$campusDirectory?'panel/mitra/kampus.php':'panel/mitra/';$filters=['q'=>$q,'jenis'=>$kind,'klaster'=>$cluster];
panel_start($user,$campusDirectory?'Kampus Dalam Negeri':'Mitra','mitra');
?>
<div class="partners-admin partners-list-page">
<header class="page-actions"><div><h1><?= panel_icon('mitra') ?> <?= $campusDirectory?'Kampus Dalam Negeri':'Mitra industri &amp; kampus' ?></h1><p>Kelola identitas mitra, kontak internal, dan dokumen kerja sama.</p></div><nav class="partner-list-toolbar" aria-label="Pengelolaan mitra"><a class="partner-add" href="<?= e(base_url('panel/mitra/tambah.php'.($campusDirectory?'?jenis=kampus':''))) ?>"><?= panel_icon('add') ?> Tambah <?= $campusDirectory?'kampus':'mitra' ?></a><a href="<?= e(base_url($campusDirectory?'panel/mitra/':'panel/mitra/kampus.php')) ?>"><?= panel_icon('program') ?> <?= $campusDirectory?'Semua mitra':'Kampus Dalam Negeri' ?></a><?php if($canMou): ?><a href="<?= e(base_url('panel/mou/')) ?>"><?= panel_icon('certificate') ?> Riwayat MoU</a><?php endif; ?></nav></header>
<?php if(!$ready): ?><p class="notice">Profil lengkap memerlukan database/updates/022_partner_profiles_mou.sql. Data mitra lama tetap tersedia.</p><?php endif; ?>
<?php if($campusDirectory): ?><p class="partner-list-note">Hanya kampus dengan negara Indonesia yang telah diisi. Lengkapi profil kampus lama melalui Semua mitra.</p><?php endif; ?>
<form class="filter-form card" method="get" data-partner-filters><label><span><?= panel_icon('search') ?> Cari nama mitra</span><input name="q" maxlength="100" value="<?= e($q) ?>" placeholder="Nama perusahaan atau kampus"></label><?php if(!$campusDirectory): ?><label><span><?= panel_icon('mitra') ?> Jenis</span><select name="jenis"><?php foreach([''=>'Semua jenis','perusahaan'=>'Perusahaan','kampus'=>'Kampus'] as $key=>$label): ?><option value="<?= $key ?>" <?= $kind===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label><span><?= panel_icon('location') ?> Klaster perusahaan</span><select name="klaster" <?= $kind==='kampus'?'disabled':'' ?>><option value="">Semua klaster</option><?php foreach(partner_clusters()+['belum'=>'Belum diklasifikasikan'] as $key=>$label): ?><option value="<?= $key ?>" <?= $cluster===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?><button type="submit"><?= panel_icon('search') ?> Cari</button><a href="<?= e(base_url($path)) ?>"><?= panel_icon('reset') ?> Reset</a></form>
<div class="partner-list-heading"><h2><?= panel_icon('mitra') ?> Daftar <?= $campusDirectory?'kampus':'mitra' ?></h2><span><?= $total ?> mitra &middot; Halaman <?= $page ?> dari <?= $pages ?></span></div>
<p class="partner-list-note"><?= panel_icon('lock') ?> Mitra aktif dapat tampil di publik. PIC dan dokumen MoU hanya untuk pengelola berizin.</p>
<div class="table-scroll partner-list-sheet" data-vertical-list tabindex="0" role="region" aria-label="Daftar mitra, gulir untuk melihat seluruh data"><table><thead><tr><th><?= panel_icon('mitra') ?> Nama / website</th><th><?= panel_icon('program') ?> Jenis / klaster</th><th><?= panel_icon('location') ?> Alamat / negara</th><th><?= panel_icon('akun') ?> PIC (internal)</th><th><?= panel_icon('check-circle') ?> Status</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach($items as $item): ?><tr><td><div class="partner-admin-identity"><?php if($item['logo']&&managed_upload_path($item['logo'])): ?><img src="<?= e(base_url($item['logo'])) ?>" alt="<?= e('Logo '.$item['nama']) ?>" width="36" height="36"><?php else: ?><span class="partner-logo-empty"><?= panel_icon('mitra') ?></span><?php endif; ?><strong><?= e($item['nama']) ?></strong></div><?php if($item['website']&&http_url($item['website'])): ?><a class="partner-website-link" href="<?= e($item['website']) ?>" target="_blank" rel="noopener noreferrer"><?= panel_icon('link') ?> Website resmi</a><?php endif; ?></td><td><strong><?= $item['jenis']==='kampus'?'Kampus':'Perusahaan' ?></strong><?php if($item['jenis']==='perusahaan'): ?><small><?= e(partner_clusters()[$item['klaster']]??'Belum diklasifikasikan') ?></small><?php endif; ?></td><td><?= nl2br(e($item['alamat_lengkap']?:'Alamat belum diisi')) ?><small><?= e($item['negara']?:'Negara belum diisi') ?></small></td><td><?= e($item['pic_nama']?:'Belum diisi') ?><?php if($item['pic_kontak']): ?><small><?= e($item['pic_kontak']) ?></small><?php endif; ?></td><td><span class="partner-state <?= $item['aktif']?'is-active':'is-inactive' ?>"><?= $item['aktif']?'Aktif':'Nonaktif' ?></span></td><td><div class="partner-row-actions"><a class="partner-view" href="<?= e(base_url('panel/mitra/detail.php?id='.$item['id'])) ?>" title="Detail / PIC" aria-label="<?= e('Detail dan PIC '.$item['nama']) ?>"><?= panel_icon('view') ?></a><a class="partner-edit" href="<?= e(base_url('panel/mitra/edit.php?id='.$item['id'])) ?>" title="Edit mitra" aria-label="<?= e('Edit '.$item['nama']) ?>"><?= panel_icon('edit') ?></a><?php if($canMou): ?><a class="partner-mou" href="<?= e(base_url('panel/mou/?mitra_id='.$item['id'])) ?>" title="Riwayat MoU" aria-label="<?= e('Riwayat MoU '.$item['nama']) ?>"><?= panel_icon('certificate') ?></a><?php endif; ?><form method="post" action="<?= e(base_url('panel/mitra/hapus.php')) ?>" data-confirm="Hapus mitra ini? Mitra yang memiliki relasi atau riwayat tidak dapat dihapus. Logo tetap di katalog media."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="version" value="<?= (int)$item['profile_version'] ?>"><button type="submit" class="partner-delete" title="Hapus mitra" aria-label="<?= e('Hapus '.$item['nama']) ?>"><?= panel_icon('trash') ?></button></form></div></td></tr><?php endforeach; ?>
<?php if(!$items): ?><tr><td colspan="6" class="empty-panel">Tidak ada mitra sesuai filter. Ubah pencarian atau gunakan Reset.</td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1):$start=max(1,min($page-2,$pages-4));$end=min($pages,$start+4); ?><nav class="pagination partner-list-pagination" aria-label="Halaman mitra"><?php if($page>1): ?><a href="<?= e(base_url($path.'?'.http_build_query($filters+['page'=>$page-1]))) ?>"><?= panel_icon('back') ?> Sebelumnya</a><?php endif; ?><?php for($n=$start;$n<=$end;$n++): ?><a class="partner-page-number" aria-label="Halaman <?= $n ?>" <?= $n===$page?'aria-current="page"':'' ?> href="<?= e(base_url($path.'?'.http_build_query($filters+['page'=>$n]))) ?>"><?= $n ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="<?= e(base_url($path.'?'.http_build_query($filters+['page'=>$page+1]))) ?>">Berikutnya <?= panel_icon('next') ?></a><?php endif; ?></nav><?php endif; ?>
</div>
<?php panel_end($user); ?>
